import{_ as a,o as d,c as r,a2 as l}from"./chunks/framework.F7eQ-ohH.js";const e="/bzygq/assets/quesion_imgs_image_1769736564200_0_1769736564231_171.Clctn_i2.png",i="/bzygq/assets/quesion_imgs_image_1769736567504_1_1769736567528_496.DAc_x5Sz.png",o="/bzygq/assets/quesion_imgs_image_1769736567504_1_1769736567528_496.DAc_x5Sz.png",n="/bzygq/assets/quesion_imgs_image_1769736577697_3_1769736577704_264.hAXusz0e.png",h="/bzygq/assets/quesion_imgs_image_1769736580529_4_1769736580546_730.DuqMrt3D.png",s="/bzygq/assets/quesion_imgs_image_1769736585671_5_1769736585704_726.C3IYHlu7.png",p="/bzygq/assets/quesion_imgs_image_1769736596119_6_1769736596134_668.BTx1-ZOG.png",g="/bzygq/assets/quesion_imgs_image_1769736600135_7_1769736600170_92.bfIB3Sb4.png",x=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"科技岗专业课/数据结构/9、排序.md","filePath":"科技岗专业课/数据结构/9、排序.md","lastUpdated":1788883925000}'),b={name:"科技岗专业课/数据结构/9、排序.md"};function u(c,t,q,_,m,O){return d(),r("div",null,[...t[0]||(t[0]=[l('<h2 id="选择排序" tabindex="-1">选择排序 <a class="header-anchor" href="#选择排序" aria-label="Permalink to &quot;选择排序&quot;">​</a></h2><h2 id="什么是选择排序" tabindex="-1">什么是选择排序 <a class="header-anchor" href="#什么是选择排序" aria-label="Permalink to &quot;什么是选择排序&quot;">​</a></h2><p>选择排序（Selection Sort）是一种简单直观的排序算法，其核心思想可以类比为&quot;每次挑出未排序元素中的最小的元素&quot;，直到所有的元素都有序。假设我们有一排学生，需要按照身高从低到高排成一列，选择排序就是最直观的做法，即：</p><ol><li>从所有学生中找到最矮的那个，让他站到第一个位置</li><li>从剩下的学生中再找最矮的，站到第二个位置</li><li>重复这个过程，直到所有学生排好队</li></ol><p>选择排序的原理正是如此：<strong>在每一轮遍历中，从剩余未排序的元素中找到最小值（或最大值），然后将其放到已排序序列的末尾。</strong></p><h2 id="算法示例" tabindex="-1">算法示例 <a class="header-anchor" href="#算法示例" aria-label="Permalink to &quot;算法示例&quot;">​</a></h2><p>假设我们有一个数组 arr = [4, 2, 5, 1, 3]，其选择排序的流程如下：</p><p><img src="'+e+'" alt=""></p><p>选择排序的固定时间复杂度为O(n²)，不依赖数据初始状态，且为原地排序（仅需常数额外空间）。</p><h2 id="冒泡排序——像气泡上浮一样简单的排序算法" tabindex="-1">冒泡排序——像气泡上浮一样简单的排序算法 <a class="header-anchor" href="#冒泡排序——像气泡上浮一样简单的排序算法" aria-label="Permalink to &quot;冒泡排序——像气泡上浮一样简单的排序算法&quot;">​</a></h2><h2 id="什么是冒泡排序" tabindex="-1">什么是冒泡排序？ <a class="header-anchor" href="#什么是冒泡排序" aria-label="Permalink to &quot;什么是冒泡排序？&quot;">​</a></h2><p>冒泡排序（Bubble Sort）的原理如同<strong>水中气泡上浮</strong>：通过<strong>反复比较相邻元素，每次遍历将最大的元素&quot;浮&quot;到数组末尾</strong>。我们可以想象一个队列，每个元素代表一个人，个子高的人不断向后移动，最终形成由矮到高的队列。冒泡排序的时间复杂度是 ，空间复杂度是 ，算法是稳定的。</p><h2 id="算法示例-1" tabindex="-1">算法示例 <a class="header-anchor" href="#算法示例-1" aria-label="Permalink to &quot;算法示例&quot;">​</a></h2><p>以数组 arr = [4, 1, 3, 1, 5，2] 为例：</p><p><img src="'+i+'" alt=""></p><p>完整排序过程需要n-1轮遍历（n为数组长度），冒泡排序的时间复杂度是 ，空间复杂度是 ，算法是稳定的。</p><h2 id="插入排序——像整理扑克牌一样排序算法" tabindex="-1">插入排序——像整理扑克牌一样排序算法 <a class="header-anchor" href="#插入排序——像整理扑克牌一样排序算法" aria-label="Permalink to &quot;插入排序——像整理扑克牌一样排序算法&quot;">​</a></h2><h2 id="什么是插入排序" tabindex="-1">什么是插入排序？ <a class="header-anchor" href="#什么是插入排序" aria-label="Permalink to &quot;什么是插入排序？&quot;">​</a></h2><p>插入排序是一种基于已经排好序的序列，将新的元素按顺序插入，使得新序列也保持有序的算法。其基本操作是将新的元素插入到已经排好序的序列中，逐步形成一个新的有序数据，适用于少量数据的排序，插入排序（Insertion Sort）的原理类似于打扑克牌时整理手牌：</p><ol><li>将手中的牌分为&quot;已排序&quot;和&quot;未排序&quot;两部分</li><li>每次从&quot;未排序&quot;部分取出一张牌</li><li>在&quot;已排序&quot;部分找到合适的位置插入</li></ol><p>插入排序的时间复杂度为O（n2），空间复杂度是O（n），是一种稳定的排序方法。</p><h2 id="算法步骤" tabindex="-1">算法步骤 <a class="header-anchor" href="#算法步骤" aria-label="Permalink to &quot;算法步骤&quot;">​</a></h2><p>以数组 arr = [3, 1, 2, 5, 4] 为例：</p><p><img src="'+o+'" alt=""></p><h2 id="快速排序——分而治之的高效排序算法" tabindex="-1">快速排序——分而治之的高效排序算法 <a class="header-anchor" href="#快速排序——分而治之的高效排序算法" aria-label="Permalink to &quot;快速排序——分而治之的高效排序算法&quot;">​</a></h2><h2 id="什么是快速排序" tabindex="-1">什么是快速排序？ <a class="header-anchor" href="#什么是快速排序" aria-label="Permalink to &quot;什么是快速排序？&quot;">​</a></h2><p>快速排序（Quick Sort），是一种常用的排序算法。它的基本思想是通过一趟排序将待排序的数据分割成独立的两部分，其中一部分的所有数据都比另一部分的所有数据都小，然后再按此方法对这两部分数据分别进行快速排序，整个排序过程可以递归进行，以达到整个数据变成有序序列的目的。快速排序（Quick Sort）采用分治策略，其核心步骤可概括为：</p><ol><li><strong>选择基准</strong>（Pivot）：从数组中选取一个元素作为基准值</li><li><strong>分区操作</strong>（Partition）：将数组分为两部分，左边元素≤基准，右边元素≥基准</li><li><strong>递归排序</strong>：对左右两个子数组重复上述步骤</li></ol><p>这就像在图书馆整理书籍：先选一本作为基准，把比它薄的放左边，厚的放右边，再分别整理左右两堆书，快速排序的时间复杂度为，空间复杂度是是一种效率较高的排序算法。</p><h2 id="算法步骤-1" tabindex="-1">算法步骤 <a class="header-anchor" href="#算法步骤-1" aria-label="Permalink to &quot;算法步骤&quot;">​</a></h2><p><img src="'+n+'" alt=""></p><p>以数组 arr = [3, 6, 8, 10, 1, 2, 1] 为例：</p><ol><li><strong>选择基准</strong>：取第一个元素3作为基准</li><li><strong>分区操作</strong>：[1，2，1，3，6，8，10]</li><li><strong>递归排序</strong>：对左半部分[1,2,1]和右半部分[6,8,10]重复上述过程</li></ol><h2 id="归并排序——分治思想的完美实践" tabindex="-1">归并排序——分治思想的完美实践 <a class="header-anchor" href="#归并排序——分治思想的完美实践" aria-label="Permalink to &quot;归并排序——分治思想的完美实践&quot;">​</a></h2><h2 id="什么是归并排序" tabindex="-1">什么是归并排序？ <a class="header-anchor" href="#什么是归并排序" aria-label="Permalink to &quot;什么是归并排序？&quot;">​</a></h2><p>归并排序是一种基于归并操作的有效排序算法，它采用分治法，将已有序的子序列合并为完全有序的序列。它的核心思想是将待排序序列不断划分为更小的子序列，直到每个子序列只有一个元素，然后将这些有序的子序列进行合并以达到排序的目的。归并排序（Merge Sort）基于分治策略，其核心步骤可概括为：</p><ol><li><strong>分解</strong>：将数组分成左右两半</li><li><strong>递归排序</strong>：对左右子数组分别递归排序</li><li><strong>合并</strong>：将两个有序子数组合并为一个有序数组</li></ol><p>以图书馆堆叠书籍为例子，假设有2个人一起来完成将书本排序的任务，那么就可以将原本的一摞树分成两半，每个人分别整理好每一半，最后将两摞有序的书合并成一摞，就完成了最终的排序任务。</p><h2 id="算法步骤-2" tabindex="-1">算法步骤 <a class="header-anchor" href="#算法步骤-2" aria-label="Permalink to &quot;算法步骤&quot;">​</a></h2><p><img src="'+h+'" alt=""></p><p>如上图所示，归并排序的整个流程可以概括为「先分后合」，通过“分”可以将排序的大问题转换成小问题，然后再逐个解决小问题最后使得整个数组有序，具体可以描述为：</p><ol><li><strong>「分」阶段（递归拆分）</strong>：</li></ol><ul><li>计算当前数组的中间索引mid，将数组拆分为左子数组[low, mid]和右子数组[mid+1, high]；</li><li>递归调用拆分方法，对左、右子数组进行同样的拆分操作；</li><li>直到子数组的长度为 1（low &gt;= high），拆分终止（长度为 1 的数组默认有序）。</li></ul><ol start="2"><li><strong>「治」阶段（合并有序数组）</strong>：</li></ol><ul><li>初始化辅助数组，暂存当前子数组的所有数据，避免合并时覆盖原数组有效数据；</li><li>用两个指针分别遍历两个有序子数组，将较小的元素依次填充回原数组；</li><li>处理其中一个子数组的剩余元素，完成合并，得到一个有序的子数组；</li><li>递归回溯，逐步合并更大的子数组，最终得到整个有序数组。</li></ul><p>归并排序适合大规模数据排序（效率稳定 O (nlogn)），但也存在空间开销大的问题，小规模数据排序时，效率不如插入排序（常数项开销更大）。</p><h2 id="堆排序——基于堆结构的高效排序算法" tabindex="-1">堆排序——基于堆结构的高效排序算法 <a class="header-anchor" href="#堆排序——基于堆结构的高效排序算法" aria-label="Permalink to &quot;堆排序——基于堆结构的高效排序算法&quot;">​</a></h2><h2 id="什么是堆" tabindex="-1">什么是堆？ <a class="header-anchor" href="#什么是堆" aria-label="Permalink to &quot;什么是堆？&quot;">​</a></h2><p>关于堆的概念，我们已经在树的章节进行过详细介绍了，不了解的同学可以看看相应章节关于<a href="https://ecnhcesakwkz.feishu.cn/wiki/PK1zwwxaRiWpDRkpLttcEebrnXb" target="_blank" rel="noreferrer">堆的定义</a>，简单来说堆就是具有极值属性的满二叉树。因此，在了解堆排序之前，我们需要先明白什么是堆，堆分为大顶堆和小顶堆：</p><ul><li><strong>大顶堆</strong>：每个节点的值都大于或等于其子节点的值，所以堆顶元素是整个堆中的最大值。</li><li><strong>小顶堆</strong>：每个节点的值都小于或等于其子节点的值，堆顶元素就是整个堆中的最小值。</li></ul><p>堆通常用数组来存储，对于数组中索引为 i 的元素，其左子节点索引为 2 * i + 1，右子节点索引为 2 * i + 2，父节点索引为 (i - 1) / 2。</p><h2 id="什么是堆排序" tabindex="-1">什么是堆排序 <a class="header-anchor" href="#什么是堆排序" aria-label="Permalink to &quot;什么是堆排序&quot;">​</a></h2><p>堆排序是一种基于<strong>堆数据结构</strong>的高效排序算法，其核心思想是利用堆 “父节点值大于（或小于）子节点值” 的特性，通过 “构建堆→交换调整→重复迭代” 的流程，逐步将无序数组转化为有序数组。该算法时间复杂度稳定为 O (nlogn)，空间复杂度为 O (1)（原地排序），适用于大数据量场景，且对缓存友好，是面试中高频考察的排序算法之一。</p><p>堆排序的核心逻辑是 “以堆为桥梁，逐步提取极值并放置到最终位置”，对于升序排序，我们通常采用<strong>大顶堆</strong>（每个父节点值 ≥ 左右子节点值）；若需降序排序，则使用小顶堆（每个父节点值 ≤ 左右子节点值），其核心逻辑如下：</p><ol><li><strong>构建堆</strong>：将初始数组构建成一个大顶堆（如果是升序排序）。</li><li><strong>交换元素并调整堆</strong>：把堆顶元素（最大值）与数组末尾元素交换，然后对剩余元素重新调整为大顶堆。</li><li><strong>重复步骤2</strong>：不断重复交换和调整的过程，直到整个数组有序。</li></ol><p>堆排序的核心优势在于高效且无需额外空间，尤其适合处理大规模数据；其关键难点在于 “堆的构建” 和 “向下调整” 的实现逻辑，面试中常要求手写堆排序代码，需重点掌握非叶子节点的调整顺序、交换后的递归 / 迭代调整逻辑。</p><h2 id="算法步骤-3" tabindex="-1">算法步骤 <a class="header-anchor" href="#算法步骤-3" aria-label="Permalink to &quot;算法步骤&quot;">​</a></h2><p>我们以数组 arr = [4, 10, 3, 5, 1] 为例，<strong>详细拆解升序堆排序的完整执行过程</strong></p><h3 id="构建大顶堆" tabindex="-1">构建大顶堆 <a class="header-anchor" href="#构建大顶堆" aria-label="Permalink to &quot;构建大顶堆&quot;">​</a></h3><p><img src="'+s+'" alt=""></p><p>初始数组：[4, 10, 3, 5, 1]构建堆的过程是依次处理所有非叶子节点（索引 1 → 索引 0），具体如下：</p><ol><li><p>处理非叶子节点1（元素值 10）</p><ul><li>该节点的左子节点索引 2*1+1=3（值 5），右子节点索引 2*1+2=4（值 1）。</li><li>比较父节点 10 与左右子节点 5、1，10 是三者最大值，满足大顶堆规则，<strong>无需调整</strong>，数组仍为 [4, 10, 3, 5, 1]。</li></ul></li><li><p>处理非叶子节点0（元素值 4）</p><ul><li>该节点的左子节点索引 2*0+1=1（值 10），右子节点索引 2*0+2=2（值 3）。</li><li>第一步：找出三者最大值，10（索引 1）＞ 4（索引 0）＞ 3（索引 2），最大值并非当前父节点，<strong>交换索引 0 和索引 1 的元素</strong>。交换后数组变为：[10, 4, 3, 5, 1]。</li><li>第二步：交换后，原子节点索引 1 现在的值为 4，需要检查该节点的子树是否满足大顶堆规则（避免交换破坏下层堆结构）。索引 1 的左子节点索引 3（值 5）、右子节点索引 4（值 1），5 ＞ 4 ＞ 1，最大值是 5（索引 3），<strong>交换索引 1 和索引 3 的元素</strong>。</li><li>交换后数组变为：[10, 5, 3, 4, 1]，此时索引 1 的子树也满足大顶堆规则。</li></ul></li></ol><h3 id="构建大顶堆完成" tabindex="-1">构建大顶堆完成 <a class="header-anchor" href="#构建大顶堆完成" aria-label="Permalink to &quot;构建大顶堆完成&quot;">​</a></h3><p>最终得到大顶堆数组：[10, 5, 3, 4, 1]（堆顶 10 为数组最大值）。</p><h3 id="交换元素并调整堆" tabindex="-1">交换元素并调整堆 <a class="header-anchor" href="#交换元素并调整堆" aria-label="Permalink to &quot;交换元素并调整堆&quot;">​</a></h3><p>该步骤需重复 n-1=4 次（只需排序前 4 个元素，最后一个元素自然有序），每次迭代都包含「交换极值」和「重构大顶堆」两个操作，具体过程如下：</p><p><img src="'+p+'" alt=""></p><ol><li><p>交换堆顶（索引 0，值 10）与当前堆末尾（索引 4，值 1），数组变为：[1, 5, 3, 4, 10]。</p><ul><li>此时 10 已到达升序排序的最终位置（数组末尾），后续无需再处理。</li></ul></li><li><p>对前 n-1=4 个元素（[1, 5, 3, 4]）重构大顶堆：</p><ul><li>从堆顶索引 0 开始调整，左子节点 1（值 5）、右子节点 2（值 3），最大值 5 交换至堆顶，数组变为 [5, 1, 3, 4, 10]。</li><li>检查交换后的子节点 1（值 1），其左子节点 3（值 4）更大，交换后数组变为 [5, 4, 3, 1, 10]，重构完成。</li></ul></li></ol><h4 id="第二步-重复上述过程-直到整个数组有序。" tabindex="-1">第二步：重复上述过程，直到整个数组有序。 <a class="header-anchor" href="#第二步-重复上述过程-直到整个数组有序。" aria-label="Permalink to &quot;第二步：重复上述过程，直到整个数组有序。&quot;">​</a></h4><p><img src="'+g+'" alt=""></p><h4 id="第三步-排序完成" tabindex="-1">第三步：排序完成 <a class="header-anchor" href="#第三步-排序完成" aria-label="Permalink to &quot;第三步：排序完成&quot;">​</a></h4><p>经过 4 次迭代交换与堆调整，整个数组完成升序排序，最终结果为：[1, 3, 4, 5, 10]。</p><h2 id="外部排序——处理海量数据的排序策略" tabindex="-1">外部排序——处理海量数据的排序策略 <a class="header-anchor" href="#外部排序——处理海量数据的排序策略" aria-label="Permalink to &quot;外部排序——处理海量数据的排序策略&quot;">​</a></h2><h2 id="什么是外部排序" tabindex="-1">什么是外部排序？ <a class="header-anchor" href="#什么是外部排序" aria-label="Permalink to &quot;什么是外部排序？&quot;">​</a></h2><p>在实际的数据处理场景中，我们常常会遇到数据量极其庞大，以至于无法一次性全部加载到计算机内存中进行排序的情况。例如，要对存储在硬盘上的数 TB 级别的日志文件进行排序，而计算机内存可能只有几十 GB。这时，传统的内部排序算法（如快速排序、归并排序等在内存中完成排序的算法）就无法直接使用了，外部排序算法应运而生。外部排序和内部排序的关键区别如下：</p><table tabindex="0"><thead><tr><th>特性</th><th>内部排序</th><th>外部排序</th></tr></thead><tbody><tr><td>数据存储</td><td>全量驻留内存</td><td>主体在外存，仅部分数据入内存处理</td></tr><tr><td>数据规模</td><td>中小型（内存可容纳）</td><td>大型/超大型（TB/PB级）</td></tr><tr><td>性能瓶颈</td><td>CPU计算开销（比较/数据移动）</td><td>I/O操作开销（磁盘读写速度比内存慢1~6个数量级）</td></tr><tr><td>典型算法</td><td>快排、堆排、归并排序等</td><td>多路归并排序（核心）、置换-选择排序等</td></tr><tr><td>优化目标</td><td>减少比较次数、降低时间复杂度</td><td>最小化I/O次数（核心）、兼顾CPU效率</td></tr></tbody></table><h2 id="多路归并排序" tabindex="-1">多路归并排序 <a class="header-anchor" href="#多路归并排序" aria-label="Permalink to &quot;多路归并排序&quot;">​</a></h2><p>外部排序的主流实现为<strong>多路归并排序</strong>，核心分为“生成初始顺串”和“多路归并”两阶段，全程围绕“减少I/O次数”设计。</p><h3 id="生成初始顺串-有序子文件" tabindex="-1">生成初始顺串（有序子文件） <a class="header-anchor" href="#生成初始顺串-有序子文件" aria-label="Permalink to &quot;生成初始顺串（有序子文件）&quot;">​</a></h3><ol><li>分批读取：按内存可用缓冲区大小，将外存数据分批读入内存；</li><li>内部排序：用高效内部排序算法（快排/堆排）对当前内存数据排序；</li><li>写回外存：将排序后的有序子文件（称为“顺串”）写回外存，重复至所有数据处理完毕。</li></ol><table tabindex="0"><thead><tr><th>示例：若内存可容纳100MB数据，对1GB文件排序，将生成10个100MB的初始顺串（顺串数量m=总数据量/内存容量，向上取整）。</th></tr></thead></table><h3 id="多路归并-合并顺串为完整有序文件" tabindex="-1">多路归并（合并顺串为完整有序文件） <a class="header-anchor" href="#多路归并-合并顺串为完整有序文件" aria-label="Permalink to &quot;多路归并（合并顺串为完整有序文件）&quot;">​</a></h3><p>将多个有序顺串逐步合并为一个全局有序文件，核心是通过“多路并行”减少归并趟数，进而降低I/O开销</p><ol><li><p>基本原理：</p><ul><li>分配k+1个内存缓冲区（k个用于读取k个顺串，1个用于输出合并结果）；</li><li>每次从k个顺串的当前待选元素中，选择最小值写入输出缓冲区；</li><li>当某一顺串的数据读取完毕，立即从外存读入该顺串的下一批数据，直至所有顺串合并完成。</li></ul></li><li><p>归并趟数计算：设初始顺串数为m，采用k路归并，总归并趟数s=⌈logₖm⌉（向上取整）。</p></li></ol><p>&gt; 示例：10个初始顺串用3路归并，需⌈log₃10⌉=2趟，远少于二路归并的⌈log₂10⌉=4趟，I/O次数大幅减少。</p><h2 id="排序算法总结" tabindex="-1">排序算法总结 <a class="header-anchor" href="#排序算法总结" aria-label="Permalink to &quot;排序算法总结&quot;">​</a></h2><h2 id="时间复杂度对比-表格" tabindex="-1">时间复杂度对比（表格） <a class="header-anchor" href="#时间复杂度对比-表格" aria-label="Permalink to &quot;时间复杂度对比（表格）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>算法名称</th><th>最坏时间复杂度</th><th>平均时间复杂度</th><th>最好时间复杂度</th><th>空间复杂度</th><th>稳定性</th></tr></thead><tbody><tr><td>冒泡排序</td><td>O(n²)</td><td>O(n²)</td><td>O(n)</td><td>O(1)</td><td>稳定</td></tr><tr><td>选择排序</td><td>O(n²)</td><td>O(n²)</td><td>O(n²)</td><td>O(1)</td><td>不稳定</td></tr><tr><td>插入排序</td><td>O(n²)</td><td>O(n²)</td><td>O(n)</td><td>O(1)</td><td>稳定</td></tr><tr><td>快速排序</td><td>O(n²)</td><td>O(n log n)</td><td>O(n log n)</td><td>O(log n)</td><td>不稳定</td></tr><tr><td>归并排序</td><td>O(n log n)</td><td>O(n log n)</td><td>O(n log n)</td><td>O(n)</td><td>稳定</td></tr><tr><td>堆排序</td><td>O(n log n)</td><td>O(n log n)</td><td>O(n log n)</td><td>O(1)</td><td>不稳定</td></tr><tr><td>桶排序</td><td>O(n²)</td><td>O(n + k)</td><td>O(n + k)</td><td>O(n + k)</td><td>稳定</td></tr><tr><td>计数排序</td><td>O(n + k)</td><td>O(n + k)</td><td>O(n + k)</td><td>O(n + k)</td><td>稳定</td></tr><tr><td>基数排序</td><td>O(d(n + k))</td><td>O(d(n + k))</td><td>O(d(n + k))</td><td>O(n + k)</td><td>稳定</td></tr><tr><td>外部排序</td><td>O(N log N)</td><td>O(N log N)</td><td>O(N log N)</td><td>O(k)</td><td>稳定</td></tr></tbody></table><h2 id="稳定性对比-表格" tabindex="-1">稳定性对比（表格） <a class="header-anchor" href="#稳定性对比-表格" aria-label="Permalink to &quot;稳定性对比（表格）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>算法名称</th><th>稳定性</th><th>说明</th></tr></thead><tbody><tr><td>冒泡排序</td><td>✅ 稳定</td><td>相同元素比较时不交换位置</td></tr><tr><td>选择排序</td><td>❌ 不稳定</td><td>交换操作可能破坏相同元素顺序</td></tr><tr><td>插入排序</td><td>✅ 稳定</td><td>从后向前扫描，保持相同元素原有顺序</td></tr><tr><td>快速排序</td><td>❌ 不稳定</td><td>分区操作可能打乱相同元素顺序</td></tr><tr><td>归并排序</td><td>✅ 稳定</td><td>合并过程中保持相同元素顺序</td></tr><tr><td>堆排序</td><td>❌ 不稳定</td><td>堆调整可能破坏相同元素顺序</td></tr><tr><td>桶排序</td><td>✅ 稳定</td><td>桶内排序采用稳定算法（如插入排序）</td></tr><tr><td>计数排序</td><td>✅ 稳定</td><td>按顺序填充结果数组</td></tr><tr><td>基数排序</td><td>✅ 稳定</td><td>按位排序时保持相同元素顺序</td></tr><tr><td>外部排序</td><td>✅ 稳定</td><td>取决于内部排序算法的稳定性（通常使用稳定算法）</td></tr></tbody></table><h2 id="真题" tabindex="-1">真题 <a class="header-anchor" href="#真题" aria-label="Permalink to &quot;真题&quot;">​</a></h2><p>| 【南方电网 2024 】下列四个序列中，哪一个是堆？ A. 75,65,30,15,25,45,20,10 B. 75,65,45,10,30,25,20,15 C. 75,45,65,30,15,25,20,10 D. 75,45,65,10,25,30,20,15 答案 ：C</p><table tabindex="0"><thead><tr><th>解析 ：四个选项最大值 75 均在最前，应为大顶堆。选项 C 中每个父节点值均大于子节点值，符合大顶堆定义。</th></tr></thead></table><p>| 【国家电网 2018 】堆的形状是一棵() A. 二叉排序树 B. 满二叉树 C. 完全二叉树 D. 平衡二叉树 答案 ：C</p><table tabindex="0"><thead><tr><th>解析 ：堆对应完全二叉树，其节点编号符合完全二叉树性质（根节点 i 的左孩子为 2i，右孩子为 2i+1）。</th></tr></thead></table><p>| 【中国邮储 2024 】堆排序是计算机科学中的一种抽象数据类型...下列哪项正确？ A. 堆排序是堆栈操作，通过 PUSH 和 POP 实现排序 B. 堆排序底层是堆栈，依赖“一端操作”特性 C. 堆排序是排序算法，底层基于堆（完全二叉树）实现 D. 堆排序与堆栈是同一概念，均支持一端插入删除 答案 ：C</p><table tabindex="0"><thead><tr><th>解析 ：堆排序是算法，堆栈是数据结构，堆排序基于堆（完全二叉树）实现。</th></tr></thead></table><p>| 【国家电网 2019 】若要求排序稳定且关键字为实数，应选哪种排序方法？ A. 直接插入 B. 直接选择 C. 堆 D. 快速 答案 ：A</p><table tabindex="0"><thead><tr><th>解析 ：直接插入排序稳定，堆排序、快速排序、直接选择排序均不稳定，实数排序选直接插入。</th></tr></thead></table><p>| 【中国铁塔 2021 】关于排序算法的说法错误的是？ A. 快速排序平均 O(nlogn)，最坏 O(n²) B. 堆排序平均 O(nlogn)，最坏 O(nlogn) C. 冒泡排序平均 O(n²)，最坏 O(n²) D. 归并排序平均 O(nlogn)，最坏 O(n²) 答案 ：D</p><table tabindex="0"><thead><tr><th>解析 ：归并排序最坏时间复杂度为 O(nlogn)，非 O(n²)。</th></tr></thead></table><p>| 【中国铁塔 2020 】对长度为 10 的线性表进行冒泡排序，最坏情况需比较多少次？ A. 9 B. 10 C. 45 D. 90 答案 ：C</p><table tabindex="0"><thead><tr><th>解析 ：冒泡排序最坏情况为逆序序列，比较次数为 9+8+…+1=45（等差数列求和 n(n-1)/2）。</th></tr></thead></table><p>| 【中国铁塔 2023】将两个各有 n 个元素的有序表归并成一个有序表，最少比较次数是？ A. 2n B. 2n-1 C. n-1 D. n 答案 ：D</p><table tabindex="0"><thead><tr><th>解析 ：当一个表所有元素大于另一个表时，仅需比较 n 次（第一个表首元素与第二个表所有元素比较）。</th></tr></thead></table>',105)])])}const P=a(b,[["render",u]]);export{x as __pageData,P as default};
